import{_ as t,c as r,o,ae as n}from"./chunks/framework.CQ8DW7XN.js";const h=JSON.parse('{"title":"Structure Your Unstructured Data","description":"","frontmatter":{},"headers":[],"relativePath":"docs/neo/neo.md","filePath":"docs/neo/neo.md"}'),a={name:"docs/neo/neo.md"};function i(s,e,l,c,u,d){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="structure-your-unstructured-data" tabindex="-1">Structure Your Unstructured Data <a class="header-anchor" href="#structure-your-unstructured-data" aria-label="Permalink to &quot;Structure Your Unstructured Data&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The <em><strong>NetApp Neo Connector: Structure Your Unstructure Data</strong></em> is a containerized solution that transfroms unstructure data from any storage platforms to consumable structured data by agents, MCP servers, and solutions like Microsoft M365 Copilot without the need to migrate or rearchitect your existing data architecture.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The NetApp Neo Connector is currently in <strong>Private Preview</strong>. This means that the connector is not yet in a General Availability release and may have some limitations.<br> The connector requires a license to activate. You can request access to the connector by joining the Early Access Program (EAP). Please book a meeting with the following link to join the EAP: <a href="https://outlook.office.com/bookwithme/user/d636d7a02ad8477c9af9a0cbb029af4d@netapp.com/meetingtype/nm-mXkp-TUO1CdzOmFfIBw2?anonymous&amp;ismsaljsauthenabled&amp;ep=mlink" target="_blank" rel="noreferrer">Book a meeting with NetApp</a>.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>OCR and Optimized Extraction</strong> - the connector automatically extracts accurate text from complex documents, making it easier to search and find relevant information in your files (the only connector in the market to provide this feature)</li><li><strong>GPU Support</strong> - the connector can leverage GPU acceleration for 2-5x faster data extraction and conversion, improving performance and reducing processing time (this is a world-first for a Copilot connector)</li><li><strong>Containerized Deployment</strong> - typical deployment time is less than 3 minutes</li><li><strong>Multiple Source Support</strong> - supports SMB File Shares (v3.1.1 through v2.0) including: <ul><li>Azure NetApp Files (ANF)</li><li>AWS FSxN</li><li>Google Cloud Volumes NetApp (GCVN)</li><li>Cloud Volumes ONTAP (CVO)</li><li>Any ONTAP-based system (FAS, AFF, Select, etc.)</li><li>Any SMB file share (non-NetApp) that supports SMB v3.1.1 through v2.0</li></ul></li><li><strong>No Data Migration Required</strong> - connect your existing NetApp storage to M365 Copilot</li><li><strong>Item level permissioning</strong> - the connector will automatically extract and convert files from the source file share and transfer them to Microsoft Graph, preserving item-level permissions</li><li><strong>API Interface</strong> - RESTful API for easy integration and management of the connector, replacing the need for M365 Search and Intelligence UI</li><li><strong>Enhanced filtering</strong> - filter data based on file type, size, and date</li><li><strong>Parallelization</strong> - multiple threads for faster data extraction, conversion and transfer</li><li><strong>Large Document Chunking</strong> - split large documents into smaller chunks for unlimited file ingestion into Microsoft Graph (MS Graph has a 3.8MB Content-Length limit, this feature allows for larger files to be ingested)</li><li><strong>Offline Licensing</strong> - no need to connect to the internet for licensing</li></ul><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>For any questions or issues, please open an issue in this repository.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p><strong>Please note that use of this software is subject to the NetApp <a href="https://www.netapp.com/how-to-buy/sales-terms-and-conditions/terms-with-customers/general-terms/general-terms/" target="_blank" rel="noreferrer">General Terms</a>.</strong></p>',10)])])}const m=t(a,[["render",i]]);export{h as __pageData,m as default};
